        v=grid[r][c]
        if v:
          for R in range(r,3*h, h):
            for C in range(c,3*w, w):
              out[R][C]=v
              # horizontal adjoining cells
              out[R][(C-1)%(3*w)]=1
              out[R][(C+1)%(3*w)]=1
